        Some(plan) => {
            writeln!(human, "First release preview (`callisto release --dry-run`):")?;
            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human)?;
        }
        None => writeln!(human, "{NO_COMMITS}")?,
